INSERT INTO regulations (recordid, citation, title, jurisdiction, agency, category, summary, url, sourceid) VALUES
  ('4f7f5b02-5c73-58fb-89cf-246d3ae70f1f', '42 CFR 431.53', 'Assurance of transportation', 'US', 'CMS', 'enrollment', 'State Medicaid plans must assure necessary transportation to and from providers.', 'https://www.ecfr.gov/current/title-42/section-431.53', '1ecdd289-2470-5742-89e0-2eca8043569e'),
  ('36c73062-6daf-5559-aea5-22adadbf5a14', '42 CFR Part 455', 'Program integrity: Medicaid provider screening and enrollment', 'US', 'CMS', 'enrollment', 'Provider screening, disclosure of 5%+ owners, SAM/exclusion database checks, revalidation.', 'https://www.ecfr.gov/current/title-42/part-455', '1ecdd289-2470-5742-89e0-2eca8043569e'),
  ('c32bb510-7763-5257-bc78-855b6dd82f27', '42 CFR 455.450', 'Screening levels for Medicaid providers', 'US', 'CMS', 'enrollment', 'Limited / moderate / high risk screening categories; high risk adds fingerprint-based checks and site visits.', 'https://www.ecfr.gov/current/title-42/section-455.450', '1ecdd289-2470-5742-89e0-2eca8043569e'),
  ('b73e2eb9-7c63-59a0-b2c5-85bc207d498f', '42 CFR Part 1001', 'OIG program integrity: exclusions', 'US', 'HHS OIG', 'enrollment', 'Exclusion authority; excluded individuals may not be employed on federally funded work. Guide: screen all staff monthly.', 'https://www.ecfr.gov/current/title-42/part-1001', '1ecdd289-2470-5742-89e0-2eca8043569e'),
  ('60a14035-6fc3-5254-a89d-2bb3d7329f48', '49 CFR 390.5', 'FMCSR definitions (commercial motor vehicle)', 'US', 'FMCSA', 'vehicle', 'GVWR 10,001+ lbs or designed for 9-15+ passengers for compensation brings a vehicle under FMCSA rules.', 'https://www.ecfr.gov/current/title-49/section-390.5', '1ecdd289-2470-5742-89e0-2eca8043569e'),
  ('e7862227-c3ac-5d0b-86f9-4587f314212f', '49 CFR Part 382', 'Controlled substances and alcohol use and testing', 'US', 'FMCSA', 'testing', 'Pre-employment, random (50% drug / 10% alcohol), post-accident, reasonable suspicion, return-to-duty testing for CDL drivers.', 'https://www.ecfr.gov/current/title-49/part-382', '1ecdd289-2470-5742-89e0-2eca8043569e'),
  ('2eec3b24-eb4c-52c9-80fb-4ae13ed68a13', '49 CFR 382.703', 'Drug and Alcohol Clearinghouse', 'US', 'FMCSA', 'testing', 'Clearinghouse queries and reporting for CDL drivers.', 'https://www.ecfr.gov/current/title-49/section-382.703', '1ecdd289-2470-5742-89e0-2eca8043569e'),
  ('8faa2a36-5435-5729-a84e-947709801cab', '49 CFR Part 391', 'Qualifications of drivers', 'US', 'FMCSA', 'driver', 'Driver qualification files; DOT medical certificate (MCSA-5876) at most every 24 months.', 'https://www.ecfr.gov/current/title-49/part-391', '1ecdd289-2470-5742-89e0-2eca8043569e'),
  ('322c5acc-8711-576b-ba49-dca4f0245633', '49 CFR Part 395', 'Hours of service of drivers', 'US', 'FMCSA', 'driver', 'Hours-of-service limits for FMCSA-regulated drivers.', 'https://www.ecfr.gov/current/title-49/part-395', '1ecdd289-2470-5742-89e0-2eca8043569e'),
  ('67a0a4f9-a0f6-581c-b457-15631a8ce7de', '49 CFR Part 396', 'Inspection, repair, and maintenance', 'US', 'FMCSA', 'vehicle', 'Systematic maintenance program; records kept for the vehicle''s life plus time after.', 'https://www.ecfr.gov/current/title-49/part-396', '1ecdd289-2470-5742-89e0-2eca8043569e'),
  ('cede0117-9f8a-59a1-bf34-0165789ecd51', '49 CFR 396.11', 'Driver vehicle inspection reports', 'US', 'FMCSA', 'vehicle', 'Daily post-trip DVIR.', 'https://www.ecfr.gov/current/title-49/section-396.11', '1ecdd289-2470-5742-89e0-2eca8043569e'),
  ('1f0b3da7-6994-5d3a-9523-baaef2c0cbc8', '49 CFR 396.17', 'Periodic inspection', 'US', 'FMCSA', 'vehicle', 'Annual inspection by a qualified inspector.', 'https://www.ecfr.gov/current/title-49/section-396.17', '1ecdd289-2470-5742-89e0-2eca8043569e'),
  ('fc1b16f2-0ee5-5dc9-aca4-59ea87dbaacc', '49 CFR 387.9', 'Financial responsibility, minimum levels', 'US', 'FMCSA', 'insurance', 'Minimum liability for interstate carriers ($750,000 cited by the guide).', 'https://www.ecfr.gov/current/title-49/section-387.9', '1ecdd289-2470-5742-89e0-2eca8043569e'),
  ('9b4d5c52-c256-569c-b338-dd7e36172653', '49 CFR Part 37', 'Transportation services for individuals with disabilities (ADA)', 'US', 'DOT', 'accessibility', 'ADA service obligations for transportation providers.', 'https://www.ecfr.gov/current/title-49/part-37', '1ecdd289-2470-5742-89e0-2eca8043569e'),
  ('7a5c84bb-0a23-5ed6-a91b-ecf65fdc0990', '49 CFR Part 38', 'ADA accessibility specifications for transportation vehicles', 'US', 'DOT', 'accessibility', 'Lift capacity (600 lb min), platform dimensions, securement, interlocks.', 'https://www.ecfr.gov/current/title-49/part-38', '1ecdd289-2470-5742-89e0-2eca8043569e'),
  ('3adb49f7-67cb-597e-bfd9-9bca1914adb6', '49 CFR Part 655', 'FTA prevention of alcohol misuse and prohibited drug use', 'US', 'FTA', 'testing', 'Testing program for FTA-funded operations.', 'https://www.ecfr.gov/current/title-49/part-655', '1ecdd289-2470-5742-89e0-2eca8043569e'),
  ('ee2cbcb6-a82f-54c3-a152-cdcd8e4efd20', '45 CFR Part 160', 'HIPAA general administrative requirements', 'US', 'HHS OCR', 'privacy', 'Definitions, enforcement, civil money penalties.', 'https://www.ecfr.gov/current/title-45/part-160', '1ecdd289-2470-5742-89e0-2eca8043569e'),
  ('2995326c-ac9a-5b56-a963-040999f512ad', '45 CFR Part 164 Subpart C', 'HIPAA Security Rule', 'US', 'HHS OCR', 'privacy', 'Administrative, physical and technical safeguards for ePHI; risk analysis; audit controls.', 'https://www.ecfr.gov/current/title-45/part-164', '1ecdd289-2470-5742-89e0-2eca8043569e'),
  ('a4e618f3-b8e1-5b4e-ac06-d289bdced8cc', '45 CFR Part 164 Subpart E', 'HIPAA Privacy Rule', 'US', 'HHS OCR', 'privacy', 'Uses and disclosures of PHI; minimum necessary; notice of privacy practices.', 'https://www.ecfr.gov/current/title-45/part-164', '1ecdd289-2470-5742-89e0-2eca8043569e'),
  ('3ff2be8b-8496-5072-845e-f725da8bb3c5', '45 CFR 164.308(a)(5)', 'Security awareness and training', 'US', 'HHS OCR', 'privacy', 'Workforce security training (guide: initial and annual).', 'https://www.ecfr.gov/current/title-45/section-164.308', '1ecdd289-2470-5742-89e0-2eca8043569e'),
  ('87508246-39a8-5f97-a782-60c32e2f4492', '45 CFR Part 164 Subpart D', 'Breach notification', 'US', 'HHS OCR', 'privacy', 'Notify individuals within 60 days; HHS and media for breaches of 500+.', 'https://www.ecfr.gov/current/title-45/part-164', '1ecdd289-2470-5742-89e0-2eca8043569e'),
  ('fc47ca85-dbe4-5e5b-9157-523ad925aece', '29 CFR 1910.1030', 'Bloodborne pathogens', 'US', 'OSHA', 'safety', 'Exposure control plan and training for employees with occupational exposure.', 'https://www.ecfr.gov/current/title-29/section-1910.1030', '1ecdd289-2470-5742-89e0-2eca8043569e'),
  ('55b9dddd-fff9-51a6-8ccf-8e386a9017a3', '42 USC 12181-12189', 'ADA Title III, public accommodations', 'US', 'DOJ', 'accessibility', 'Accessibility obligations for private transportation services.', 'https://www.law.cornell.edu/uscode/text/42/chapter-126/subchapter-III', '1ecdd289-2470-5742-89e0-2eca8043569e'),
  ('bf0cc2cd-760c-53b8-8076-46555be4f2c5', '31 USC 3729', 'False Claims Act', 'US', 'DOJ', 'billing', 'Civil liability for false claims: per-claim penalties plus treble damages.', 'https://www.law.cornell.edu/uscode/text/31/3729', '1ecdd289-2470-5742-89e0-2eca8043569e'),
  ('30d2b0fc-26fc-59e0-b4f5-f7387b501fb9', '18 USC 1347', 'Health care fraud', 'US', 'DOJ', 'billing', 'Criminal health care fraud: up to 10 years and fines.', 'https://www.law.cornell.edu/uscode/text/18/1347', '1ecdd289-2470-5742-89e0-2eca8043569e'),
  ('387d659a-291a-5472-a155-46859bc6f177', '42 USC 1320a-7b(b)', 'Anti-Kickback Statute', 'US', 'HHS OIG', 'billing', 'Prohibits remuneration for Medicaid referrals.', 'https://www.law.cornell.edu/uscode/text/42/1320a-7b', '1ecdd289-2470-5742-89e0-2eca8043569e'),
  ('518c11d1-2704-5ae9-9f9b-d7601facb752', '21st Century Cures Act § 12006', 'Electronic visit verification', 'US', 'CMS', 'billing', 'EVV mandate the guide applies to GPS-verified trip documentation.', NULL, '1ecdd289-2470-5742-89e0-2eca8043569e'),
