  ('e9014641-4c68-542c-8004-469f932cdec0', 'Fla. Stat. 409.907', 'Medicaid provider agreements', 'FL', 'AHCA', 'enrollment', 'Florida Medicaid provider enrollment, agreements and background screening of providers.', NULL, '5072c240-88a4-5706-b591-3a6f6b32d515'),
